mkdir -p /tmp/gbrain-scripts && cat > /tmp/gbrain-scripts/mcp.ts <<'EOF'
// Minimal stdio MCP client: spawns the exact command registered in Claude Code.
// usage: bun mcp.ts list | bun mcp.ts call <tool> '<json-args>'
const cfg = JSON.parse(await Bun.file("/harness-state/claude/.claude.json").text()).mcpServers.gbrain;
const p = Bun.spawn([cfg.command, ...cfg.args], { stdin: "pipe", stdout: "pipe", stderr: "inherit", env: { ...process.env, ...cfg.env } });
let buf = "", id = 0; const waiters = new Map<number, (m: any) => void>();
(async () => { for await (const c of p.stdout) { buf += new TextDecoder().decode(c); let i;
  while ((i = buf.indexOf("\n")) >= 0) { const l = buf.slice(0, i); buf = buf.slice(i + 1); if (!l.trim()) continue;
    const m = JSON.parse(l); if (m.id != null && waiters.has(m.id)) { waiters.get(m.id)!(m); waiters.delete(m.id); } } } })();
const rpc = (method: string, params: any) => new Promise<any>(r => { const n = ++id; waiters.set(n, r); p.stdin.write(JSON.stringify({ jsonrpc: "2.0", id: n, method, params }) + "\n"); p.stdin.flush(); });
await rpc("initialize", { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "install-check", version: "1" } });
p.stdin.write(JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }) + "\n");
const [cmd, tool, args] = process.argv.slice(2);
const res = cmd === "list" ? await rpc("tools/list", {}) : await rpc("tools/call", { name: tool, arguments: JSON.parse(args || "{}") });
if (cmd === "list") for (const t of res.result.tools) console.log(t.name, "-", JSON.stringify(t.inputSchema?.required ?? []));
else console.log(JSON.stringify(res.result ?? res.error, null, 1));
p.stdin.end(); p.kill(); process.exit(0);
EOF
export PATH="$HOME/.bun/bin:$PATH"; cd /tmp && timeout 120 bun /tmp/gbrain-scripts/mcp.ts list

